// S-A live gate (card t_00fda230): the SHIPPED tactical_mission_critical.json
// (generated by tools/mission_critical_mine.py) must mirror the shipped
// mission corpus exactly - zero fixtures. Laws checked against the REAL
// mission files in Assets/Resources/SagaMissions:
//   1. schema + one row per shipped mission (138), file/GUID identity holds.
//   2. every critical row's entity GUID exists in that mission's mapEntities
//      and its name/entityType match the mission file; a "terminal" row is
//      terminal in the file too (no invented criticality).
//   3. terminal completeness: EVERY Terminal entity of every shipped mission
//      carries a critical row (the heuristics floor - none may be dropped).
//   4. section rows mirror the mission sections (GUID/name/invisible flag);
//      every hypothesis edge's section + entities resolve inside the row's
//      own mission (a hypothesis may point at nothing - never at a phantom).
//   5. runtimeSwapped is exactly the entityGroups-membership fact.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using TacticalAI.Core;

public static class MissionCriticalGate
{
    static int fails = 0;
    static void Ok(bool cond, string what)
    {
        Console.WriteLine((cond ? "PASS " : "FAIL ") + what);
        if (!cond) fails++;
    }

    static readonly string App =
        "/home/open/work/ia-ai/ImperialCommander2/ImperialCommander2";

    // Null-safe string read: the mission files may carry null names where
    // the generator (data-existence law) wrote ""; "" and null are the same
    // claim here.
    static string S(Dictionary<string, object> d, string k)
        => Json.AsStr(Json.Get(d, k, null)) ?? "";

    static readonly Dictionary<long, string> EntityTypeNames = new Dictionary<long, string>
    {
        { 0, "Tile" }, { 1, "Terminal" }, { 2, "Crate" }, { 3, "DeploymentPoint" },
        { 4, "Token" }, { 5, "Highlight" }, { 6, "Door" },
    };

    public static void Run()
    {
        var assetPath = Path.Combine(App, "Assets", "Resources", "Languages", "En",
                                     "tactical_mission_critical.json");
        if (!File.Exists(assetPath))
        {
            Console.WriteLine("FAIL tactical_mission_critical.json missing");
            Environment.ExitCode = 1;
            Console.WriteLine("MissionCriticalGate: 1 FAIL");
            return;
        }
        var doc = Json.AsDict(Json.Parse(File.ReadAllText(assetPath)));
        var meta = Json.AsDict(Json.Get(doc, "_meta", null) ?? new Dictionary<string, object>());
        Ok(Json.AsStr(Json.Get(meta, "schema", "")) == "tacai.mission_critical/1",
           "schema == tacai.mission_critical/1");

        var rows = Json.AsList(Json.Get(doc, "missions", new List<object>()));

        // every shipped mission file, keyed by its fileName
        var missionFiles = Directory
            .GetFiles(Path.Combine(App, "Assets", "Resources", "SagaMissions"), "*.json",
                      SearchOption.AllDirectories)
            .OrderBy(p => p, StringComparer.Ordinal)
            .ToList();
        Ok(rows.Count == missionFiles.Count,
           "row count == shipped mission count (" + rows.Count + "/" + missionFiles.Count + ")");

        int terminalsSeen = 0, swappedSeen = 0;
        foreach (var p in missionFiles)
        {
            var m = Json.AsDict(Json.Parse(File.ReadAllText(p)));
            string file = Path.GetFileName(p);
            var row = rows.Cast<object>()
                .Select(Json.AsDict)
                .FirstOrDefault(r => Json.AsStr(Json.Get(r, "file", "")) == file);
            if (row == null)
            {
                Console.WriteLine("FAIL no table row for mission file " + file);
                fails++;
                continue;
            }

            // identity
            bool ident = S(row, "missionGuid") == S(m, "missionGUID");
            if (!ident) { Console.WriteLine("FAIL row identity mismatch " + file); fails++; }

            var ents = Json.AsList(Json.Get(m, "mapEntities", new List<object>()))
                            .Select(Json.AsDict).ToList();
            var entById = new Dictionary<string, Dictionary<string, object>>();
            foreach (var e in ents) entById[Json.AsStr(Json.Get(e, "GUID", ""))] = e;
            var secs = Json.AsList(Json.Get(m, "mapSections", new List<object>()))
                            .Select(Json.AsDict).ToList();
            var secById = new Dictionary<string, Dictionary<string, object>>();
            foreach (var s in secs) secById[Json.AsStr(Json.Get(s, "GUID", ""))] = s;
            var swapped = new HashSet<string>();
            foreach (var g in Json.AsList(Json.Get(m, "entityGroups", new List<object>()))
                              .Select(Json.AsDict))
                foreach (var g2 in Json.AsList(Json.Get(g, "missionEntities", new List<object>())))
                    swapped.Add(Json.AsStr(g2));

            // sections mirror
            var rowSecs = Json.AsList(Json.Get(row, "sections", new List<object>()))
                              .Select(Json.AsDict).ToList();
            if (rowSecs.Count != secs.Count)
            { Console.WriteLine("FAIL section count " + file + " " + rowSecs.Count + "/" + secs.Count); fails++; }
            foreach (var rs in rowSecs)
            {
                var sid = Json.AsStr(Json.Get(rs, "section", ""));
                Dictionary<string, object> s;
                if (!secById.TryGetValue(sid, out s))
                { Console.WriteLine("FAIL unknown section " + sid + " in " + file); fails++; continue; }
                if (S(rs, "name") != S(s, "name") ||
                    Json.AsBool(Json.Get(rs, "invisibleUntilActivated", false)) !=
                    Json.AsBool(Json.Get(s, "invisibleUntilActivated", false)))
                { Console.WriteLine("FAIL section row drift " + sid + " in " + file); fails++; }
            }

            // critical rows resolve + terminal fidelity
            var crit = Json.AsList(Json.Get(row, "criticalEntities", new List<object>()))
                           .Select(Json.AsDict).ToList();
            foreach (var c in crit)
            {
                var eid = Json.AsStr(Json.Get(c, "entity", ""));
                Dictionary<string, object> e;
                if (!entById.TryGetValue(eid, out e))
                { Console.WriteLine("FAIL phantom critical entity " + eid + " in " + file); fails++; continue; }
                var tName = EntityTypeNames.ContainsKey(Json.AsLong(Json.Get(e, "entityType", -1)))
                            ? EntityTypeNames[Json.AsLong(Json.Get(e, "entityType", -1))] : "?";
                if (Json.AsStr(Json.Get(c, "entityType", "")) != tName ||
                    S(c, "name") != S(e, "name"))
                { Console.WriteLine("FAIL critical row drift " + eid + " in " + file); fails++; }
                var reason = Json.AsStr(Json.Get(c, "reason", ""));
                if (reason == "terminal" && tName != "Terminal")
                { Console.WriteLine("FAIL non-terminal marked terminal: " + eid + " in " + file); fails++; }
                bool sw = Json.AsBool(Json.Get(c, "runtimeSwapped", false));
                if (sw != swapped.Contains(eid))
                { Console.WriteLine("FAIL runtimeSwapped != entityGroups membership: " + eid + " in " + file); fails++; }
                if (sw) swappedSeen++;
            }

            // terminal completeness: every Terminal entity has a row
            var critIds = new HashSet<string>(crit.Select(c => Json.AsStr(Json.Get(c, "entity", ""))));
            foreach (var e in ents.Where(e => Json.AsLong(Json.Get(e, "entityType", -1)) == 1))
            {
                terminalsSeen++;
                if (!critIds.Contains(Json.AsStr(Json.Get(e, "GUID", ""))))
                { Console.WriteLine("FAIL terminal missing from critical rows: " +
                                    Json.AsStr(Json.Get(e, "GUID", "")) + " in " + file); fails++; }
            }

            // hypothesis edges resolve inside their own mission
            foreach (var h in Json.AsList(Json.Get(row, "sectionHypotheses", new List<object>()))
                                .Select(Json.AsDict))
            {
                var sec = Json.AsStr(Json.Get(h, "section", ""));
                if (sec.Length > 0 && !secById.ContainsKey(sec))
                { Console.WriteLine("FAIL hypothesis edge names unknown section " + sec + " in " + file); fails++; }
                foreach (var en in Json.AsList(Json.Get(h, "entities", new List<object>())).Select(Json.AsDict))
                    if (!entById.ContainsKey(Json.AsStr(Json.Get(en, "entity", ""))))
                    { Console.WriteLine("FAIL hypothesis edge names phantom entity in " + file); fails++; }
            }
        }

        Ok(terminalsSeen > 0, "terminal census non-empty (" + terminalsSeen + " shipped terminals)");
        if (fails > 0) Environment.ExitCode = 1;
        Console.WriteLine("MissionCriticalGate: " + (fails == 0 ? "ALL PASS" : fails + " FAIL") +
                          " | rows=" + rows.Count + " terminals=" + terminalsSeen +
                          " swappedMarked=" + swappedSeen);
    }
}
